package main

func RemoveDuplicates(input []int) []int {
	result := []int{}
	for _, item := range input {
		found := false
		for _, existing := range result {
			if existing == item {
				found = true
				break
			}
		}
		if !found {
			result = append(result, item)
		}
	}
	return result
}

func main() {
	println(len(RemoveDuplicates([]int{1, 2, 2, 3})))
}

