package main

import (
	"math/rand"
	"reflect"
	"testing"
	"time"
)

func TestRemoveDuplicatesCorrectness(t *testing.T) {
	got := RemoveDuplicates([]int{1, 2, 2, 3, 1, 4, 3})
	want := []int{1, 2, 3, 4}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestRemoveDuplicatesPerformance(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	input := make([]int, 30000)
	for i := range input {
		input[i] = rnd.Intn(2000000)
	}
	seen := make(map[int]struct{}, len(input))
	expected := make([]int, 0, len(input))
	for _, v := range input {
		if _, ok := seen[v]; !ok {
			seen[v] = struct{}{}
			expected = append(expected, v)
		}
	}

	start := time.Now()
	got := RemoveDuplicates(input)
	elapsed := time.Since(start)

	if !reflect.DeepEqual(got, expected) {
		t.Fatalf("dedup result incorrect for large input")
	}
	if elapsed > 50*time.Millisecond {
		t.Fatalf("RemoveDuplicates took %v for 30000 elements, expected an O(n) map-based implementation under 50ms", elapsed)
	}
}
